// @r_peredelkino · local control of authored garden art and restaurant shade.
// These controls affect the model; they do not operate equipment in a real building.
export function createGardenControls(host,{garden,onClose=()=>{},onFitness=()=>{}}={}){
 const dialog=document.createElement('dialog');dialog.className='rp-garden-controls';dialog.setAttribute('aria-label','Управление садом');
 dialog.innerHTML='<small>@r_peredelkino / АВТОРСКАЯ КОНЦЕПЦИЯ</small><button data-garden-close aria-label="Закрыть панель">×</button><h2 data-garden-title>Дыхание сада</h2><p data-garden-copy></p><div data-garden-art><div class="rp-garden-modes"><button data-garden-mode="calm">Тихий сад</button><button data-garden-mode="pulse">Пульс</button><button data-garden-mode="social">Встреча</button></div><label>Яркость света <input data-garden-intensity type="range" min="0" max="1" step="0.05"><output data-intensity-value></output></label></div><div data-garden-restaurant hidden><div class="rp-garden-modes"><button data-shade="0">Открыть небо</button><button data-shade="0.55">Мягкая тень</button><button data-shade="1">Закрыть ламели</button></div><button data-garden-fitness>Фитнес · второй этаж →</button></div><p class="rp-garden-status" data-garden-status role="status" aria-live="polite"></p><button data-garden-done>Продолжить прогулку</button>';
 host.append(dialog);let active=false,previousFocus=null,mode='garden-art';
 const listeners=[];const bind=(node,event,fn)=>{node.addEventListener(event,fn);listeners.push(()=>node.removeEventListener(event,fn));};
 function refresh(){const state=garden?.state||{};dialog.dataset.mode=state.mode||'calm';dialog.dataset.intensity=String(state.intensity??.7);for(const b of dialog.querySelectorAll('[data-garden-mode]'))b.setAttribute('aria-pressed',String(b.dataset.gardenMode===dialog.dataset.mode));const slider=dialog.querySelector('[data-garden-intensity]');slider.value=String(state.intensity??.7);dialog.querySelector('[data-intensity-value]').textContent=Math.round(Number(slider.value)*100)+'%';for(const b of dialog.querySelectorAll('[data-shade]'))b.setAttribute('aria-pressed',String(Math.abs(Number(b.dataset.shade)-(state.shade??.55))<.01));dialog.querySelector('[data-garden-status]').textContent=mode==='terrace-restaurant'?'Ламели меняют положение в 3D. Терраса — авторское предложение для ресторана.':'Режим и свет меняются прямо в саду. Можно закрыть панель и осмотреть объект со всех сторон.';}
 function close(){if(!active)return;active=false;dialog.close();onClose();if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});}
 function open(type='garden-art'){if(!garden)return false;mode=type;previousFocus=document.activeElement;dialog.dataset.kind=type;dialog.querySelector('[data-garden-art]').hidden=type==='terrace-restaurant';dialog.querySelector('[data-garden-restaurant]').hidden=type!=='terrace-restaurant';dialog.querySelector('[data-garden-title]').textContent=type==='terrace-restaurant'?'Ресторанная терраса':'Дыхание сада';dialog.querySelector('[data-garden-copy]').textContent=type==='terrace-restaurant'?'Тёплое дерево, мягкая подсветка, зелёные борта и регулируемая тень. Сначала выберите положение навеса, затем продолжите прогулку среди столиков.':'Низкий кинетический световой сад: спокойное дыхание, волна или ритм встречи. Настройте атмосферу без изменения исходных дорожек и фасадов.';refresh();if(!active){active=true;dialog.showModal();}dialog.querySelector('[data-garden-close]').focus({preventScroll:true});return true;}
 for(const b of dialog.querySelectorAll('[data-garden-mode]'))bind(b,'click',()=>{garden.setMode(b.dataset.gardenMode);refresh();});
 bind(dialog.querySelector('[data-garden-intensity]'),'input',e=>{garden.setIntensity(Number(e.target.value));refresh();});
 for(const b of dialog.querySelectorAll('[data-shade]'))bind(b,'click',()=>{garden.setShade(Number(b.dataset.shade));refresh();});
 bind(dialog.querySelector('[data-garden-fitness]'),'click',()=>{close();onFitness();});
 for(const b of dialog.querySelectorAll('[data-garden-close],[data-garden-done]'))bind(b,'click',close);
 bind(dialog,'cancel',e=>{e.preventDefault();close();});bind(dialog,'keydown',e=>{e.stopPropagation();if(e.code==='Escape'){e.preventDefault();if(!e.repeat)close();}});
 return{open,close,refresh,get enabled(){return active;},get dialog(){return dialog;},dispose(){close();listeners.forEach(fn=>fn());dialog.remove();}};
}
